// ===========================================================================
// Bibliothèque métier commune, injectée dans chaque nœud Code au moment du
// build du workflow. NE PAS ÉDITER ICI : toute modification serait écrasée à
// la prochaine génération. Elle est écrite et testée hors n8n, puis injectée,
// pour que le code exécuté et le code couvert par la recette soient le même.
// ===========================================================================
/* ===========================================================================
 * Moteur de décision — Suivi proactif des commandes clients
 * ---------------------------------------------------------------------------
 * SOURCE DE VÉRITÉ du moteur métier.
 *
 * Cette bibliothèque est écrite et testée hors n8n, puis injectée dans les
 * nœuds Code au moment du build. Le code exécuté ici et le code couvert par
 * la recette sont donc, par construction, le même code.
 *
 * Contraintes respectées :
 *   - aucune dépendance npm ;
 *   - aucun accès réseau, aucun accès disque ;
 *   - fonctions pures : même entrée -> même sortie, aucun effet de bord ;
 *   - toutes les dates sont des chaînes 'YYYY-MM-DD' (comparables
 *     lexicographiquement, donc chronologiquement) ;
 *   - tous les délais sont comptés en JOURS OUVRÉS.
 * =========================================================================== */

/* ---------------------------------------------------------------------------
 * 1. Configuration
 * ---------------------------------------------------------------------------
 * Valeurs par défaut. Dans n8n, le nœud `Config` les surcharge intégralement :
 * rien n'est codé en dur ailleurs que dans ce bloc.
 * ------------------------------------------------------------------------- */

var CONFIG_DEFAUT = {
  MODE: 'dry_run', // 'dry_run' | 'prod'

  // Chaîne de production (jours ouvrés)
  DELAI_PREPARATION_JOURS: 2, // réception complète -> remise au transporteur
  DELAI_LIVRAISON_JOURS: 1, // remise au transporteur -> livraison

  // Engagements de recontact (jours ouvrés)
  RECONTACT_PREMIER_JOURS: 3, // après le premier message sans date
  RECONTACT_RELANCE_JOURS: 5, // entre deux points de situation

  // Marge ajoutée à l'ETA plancher AVANT de l'annoncer au client.
  // Le plancher est le minimum physiquement atteignable — pas une prévision.
  // L'annoncer tel quel comme date ferme, c'est promettre le meilleur cas
  // possible : le moindre aléa casse l'engagement, et l'on bascule en
  // « deuxième glissement » pour une commande qui arrive le lendemain.
  // La marge ne change RIEN à la détection du retard, seulement à la promesse.
  MARGE_ENGAGEMENT_JOURS: 1,

  // Coupe-circuit : au-delà de ce nombre d'emails sur une exécution, on
  // suspend tous les envois et on alerte. Un volume anormal signale un bug en
  // amont (ERP qui renvoie n'importe quoi, table d'état vidée), pas un besoin
  // réel d'écrire à 200 clients le même matin.
  SEUIL_COUPE_CIRCUIT: 25,

  // Seuils d'alerte interne (jours ouvrés)
  SEUIL_ESCALADE_FOURNISSEUR: 5,
  SEUIL_ESCALADE_CRITIQUE: 10,
  SEUIL_PREPARATION_BLOQUEE: 2,
  // Avec le plancher corrigé, une commande vue `Expediee` depuis 1 jour ouvré
  // aurait déjà dû être livrée hier : c'est le bon moment pour suspecter le
  // transporteur, pas deux jours plus tard.
  SEUIL_EXPEDITION_BLOQUEE: 1,

  // Garde-fou : au-delà, on passe la main à l'humain
  MAX_MESSAGES_AUTO: 3,

  // Cadence de rappel d'une alerte interne dont le motif n'a pas changé.
  // Sans cela, une commande durablement bloquée réapparaît dans le digest
  // chaque matin : le digest devient du bruit et l'équipe cesse de le lire.
  CADENCE_ALERTE_INTERNE_JOURS: 5,

  // Destinataire du digest interne
  EMAIL_SUPPORT: 'support@exemple.fr',

  // Canal des alertes internes : 'ticket' | 'email' | 'les_deux'.
  // Un digest dit ce qui se passe aujourd'hui ; un ticket garde la trace d'un
  // dossier dans le temps et sait qui s'en occupe. Le second remplace le
  // premier, mais le premier reste disponible sans rien recâbler.
  CANAL_ALERTE: 'ticket',
  TICKET_PROJET: 'SUP',
  TICKET_TYPE: 'Task',
  TICKET_PREFIXE_ETIQUETTE: 'suivi-commande',

  // Signature des messages clients (un humain joignable, avec un prénom)
  SIGNATURE_PRENOM: 'Camille Vasseur',
  SIGNATURE_ROLE: 'Service clients',
  SIGNATURE_SOCIETE: 'VLD',
  SIGNATURE_TEL: '01 84 20 33 10',

  // Identité de marque dans les emails HTML
  MARQUE_NOM: 'VLD',
  MARQUE_MONOGRAMME: 'V',
  MARQUE_BASELINE: 'Équipement professionnel',
  MARQUE_COULEUR: '#0E4A5F',
  // Vide = logo typographique, toujours visible même images bloquées.
  // Renseigner une URL de PNG hébergé bascule sur l'image.
  MARQUE_LOGO_URL: '',

  // Portail de suivi client. Le lien pointe vers l'état de la commande tel que
  // le workflow le connaît, pas vers un faux tracking transporteur.
  URL_PORTAIL_SUIVI: 'https://suivi.vld.example/commande',
  SECRET_LIEN_SUIVI: 'a-remplacer-par-un-secret-d-instance',

  // Jours fériés France métropolitaine, format YYYY-MM-DD.
  // ATTENTION : liste finie. Au-delà de la dernière année couverte, tous les
  // jours seraient comptés ouvrés, sans erreur visible. À compléter chaque
  // année — ou à remplacer par un calcul de Pâques si la liste devient une
  // charge de maintenance.
  JOURS_FERIES: [
    // 2026
    '2026-01-01', // Jour de l'an
    '2026-04-06', // Lundi de Pâques
    '2026-05-01', // Fête du Travail
    '2026-05-08', // Victoire 1945
    '2026-05-14', // Ascension
    '2026-05-25', // Lundi de Pentecôte
    '2026-07-14', // Fête nationale
    '2026-08-15', // Assomption
    '2026-11-01', // Toussaint
    '2026-11-11', // Armistice
    '2026-12-25', // Noël
    // 2027
    '2027-01-01',
    '2027-03-29', // Lundi de Pâques
    '2027-05-01',
    '2027-05-06', // Ascension
    '2027-05-08',
    '2027-05-17', // Lundi de Pentecôte
    '2027-07-14',
    '2027-08-15',
    '2027-11-01',
    '2027-11-11',
    '2027-12-25',
    // 2028
    '2028-01-01',
    '2028-04-17', // Lundi de Pâques
    '2028-05-01',
    '2028-05-08',
    '2028-05-25', // Ascension
    '2028-06-05', // Lundi de Pentecôte
    '2028-07-14',
    '2028-08-15',
    '2028-11-01',
    '2028-11-11',
    '2028-12-25'
  ]
};

/* ---------------------------------------------------------------------------
 * 2. Calendrier ouvré
 * ---------------------------------------------------------------------------
 * Tout est calculé sur des dates UTC à minuit : on ne manipule que des dates
 * civiles, jamais des instants. Aucun décalage possible au passage à l'heure
 * d'été / d'hiver en Europe/Paris.
 * ------------------------------------------------------------------------- */

function parseDate(valeur) {
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(valeur || ''));
  if (!m) return null;
  return new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
}

function formatDate(d) {
  return d.toISOString().slice(0, 10);
}

function ajouterJoursCalendaires(d, n) {
  var x = new Date(d.getTime());
  x.setUTCDate(x.getUTCDate() + n);
  return x;
}

function estWeekend(d) {
  var j = d.getUTCDay();
  return j === 0 || j === 6;
}

/** Un jour ouvré = ni samedi, ni dimanche, ni jour férié. */
function estJourOuvre(dateStr, joursFeries) {
  var d = parseDate(dateStr);
  if (!d) return false;
  if (estWeekend(d)) return false;
  return (joursFeries || []).indexOf(formatDate(d)) === -1;
}

/**
 * addBusinessDays('2026-09-04', 1) -> '2026-09-07' (vendredi + 1 ouvré = lundi)
 * n = 0 renvoie la date telle quelle (même si elle n'est pas ouvrée).
 * n négatif recule.
 */
function addBusinessDays(dateStr, n, joursFeries) {
  var d = parseDate(dateStr);
  if (!d) return null;
  var feries = joursFeries || [];
  var pas = n < 0 ? -1 : 1;
  var reste = Math.abs(Number(n) || 0);
  while (reste > 0) {
    d = ajouterJoursCalendaires(d, pas);
    if (!estWeekend(d) && feries.indexOf(formatDate(d)) === -1) reste--;
  }
  return formatDate(d);
}

/**
 * Nombre de jours ouvrés strictement après `depuis` et jusqu'à `jusqua` inclus.
 * diffBusinessDays(x, x) = 0 ; vendredi -> lundi = 1 ; négatif si jusqua < depuis.
 */
function diffBusinessDays(depuis, jusqua, joursFeries) {
  var a = parseDate(depuis);
  var b = parseDate(jusqua);
  if (!a || !b) return 0;
  if (a.getTime() === b.getTime()) return 0;
  var feries = joursFeries || [];
  var sens = b.getTime() > a.getTime() ? 1 : -1;
  var curseur = sens > 0 ? a : b;
  var fin = sens > 0 ? b : a;
  var n = 0;
  while (curseur.getTime() < fin.getTime()) {
    curseur = ajouterJoursCalendaires(curseur, 1);
    if (!estWeekend(curseur) && feries.indexOf(formatDate(curseur)) === -1) n++;
  }
  return n * sens;
}

/**
 * Date du jour dans le fuseau demandé, au format 'YYYY-MM-DD'.
 *
 * `toLocaleDateString('sv-SE')` est le moyen le plus court d'obtenir une date
 * ISO dans un fuseau donné, mais il dépend d'ICU : dans un runtime compilé en
 * small-icu, il retombe sur un format américain ('9/6/2026'). Le moteur
 * considérerait alors la date comme invalide et supprimerait TOUS les emails,
 * silencieusement. D'où le contrôle et le repli explicites.
 */
function dateDuJour(fuseau) {
  try {
    var s = new Date().toLocaleDateString('sv-SE', { timeZone: fuseau || 'Europe/Paris' });
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  } catch (e) {
    // Intl indisponible ou fuseau inconnu : on retombe sur UTC.
  }
  // UTC ne diffère de Paris qu'entre minuit et 2h du matin ; le workflow
  // tourne à 7h, l'écart est sans conséquence.
  return new Date().toISOString().slice(0, 10);
}

/** '2026-09-10' -> '10/09/2026' (format des dates dans les messages clients). */
function formatFr(dateStr) {
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(dateStr || ''));
  return m ? m[3] + '/' + m[2] + '/' + m[1] : '';
}

/* ---------------------------------------------------------------------------
 * 3. Table d'état (mémoire du workflow)
 * ---------------------------------------------------------------------------
 * L'ERP ne fournit pas la date de changement de statut : le workflow la
 * reconstruit. Une ligne par commande, clé `order_number`.
 * ------------------------------------------------------------------------- */

var COLONNES_ETAT = [
  'order_number',
  'company',
  'contact_email',
  'statut_erp',
  'statut_depuis',
  'delivery_date_erp',
  'date_annoncee',
  'etat_comm',
  'date_dernier_message',
  'nb_messages_client',
  'date_prochain_contact',
  'escalade_interne_le',
  'premiere_vue_le',
  // Deux colonnes ajoutées au modèle du brief, justifiées dans le README :
  'dernier_motif_escalade', // pour n'alerter que sur « même commande ET même motif »
  'ajustement_utilise', // 'oui' une fois M6 consommé : un seul rattrapage par commande
  'ticket_ref' // référence du ticket ouvert pour cette commande, vide s'il n'y en a pas
];

var ETATS_COMM = ['AUCUN', 'RETARD_SANS_DATE', 'RETARD_DATE', 'EXPEDITION_NOTIFIEE', 'CLOS'];

/** Ligne vierge pour une commande jamais vue. */
function etatVierge(commande, aujourdhui) {
  return {
    order_number: commande.order_number,
    company: commande.company || '',
    contact_email: commande.contact_email || '',
    statut_erp: '',
    statut_depuis: '',
    delivery_date_erp: commande.delivery_date || '',
    date_annoncee: '',
    etat_comm: 'AUCUN',
    date_dernier_message: '',
    nb_messages_client: 0,
    date_prochain_contact: '',
    escalade_interne_le: '',
    premiere_vue_le: aujourdhui,
    dernier_motif_escalade: '',
    ajustement_utilise: '',
    ticket_ref: ''
  };
}

/**
 * Normalise une ligne lue depuis Google Sheets : toutes les cellules arrivent
 * en chaîne, les cellules vides peuvent arriver en `undefined` ou `null`.
 */
function normaliserEtat(ligne) {
  var out = {};
  for (var i = 0; i < COLONNES_ETAT.length; i++) {
    var c = COLONNES_ETAT[i];
    var v = ligne ? ligne[c] : undefined;
    out[c] = v === undefined || v === null ? '' : String(v).trim();
  }
  out.nb_messages_client = Number(out.nb_messages_client) || 0;
  if (ETATS_COMM.indexOf(out.etat_comm) === -1) out.etat_comm = 'AUCUN';
  return out;
}

/* ---------------------------------------------------------------------------
 * 4. ETA plancher
 * ---------------------------------------------------------------------------
 * Le plancher est le minimum PHYSIQUEMENT ATTEIGNABLE, pas une prévision.
 * C'est lui — et non le statut seul — qui détecte le retard, y compris avant
 * que la date promise ne soit passée.
 * ------------------------------------------------------------------------- */

function etaPlancher(status, aujourdhui, ancienneteStatut, cfg) {
  var f = cfg.JOURS_FERIES;
  var prepa = Number(cfg.DELAI_PREPARATION_JOURS);
  var livr = Number(cfg.DELAI_LIVRAISON_JOURS);

  if (status === 'Commande_confirmee') {
    // 0 j fournisseur (au mieux, tout arrive aujourd'hui) + prépa + livraison
    return addBusinessDays(aujourdhui, prepa + livr, f);
  }
  if (status === 'En_preparation') {
    // ce qu'il reste de préparation, plancher à 0, + livraison
    return addBusinessDays(aujourdhui, Math.max(0, prepa - ancienneteStatut) + livr, f);
  }
  if (status === 'Expediee') {
    // Le workflow tourne à 7 h : une commande vue `Expediee` ce matin a été
    // remise au transporteur hier au plus tard — le passage de statut s'est
    // produit entre l'exécution d'hier et celle d'aujourd'hui. Avec un
    // transporteur à J+1, elle est donc livrable AUJOURD’HUI.
    //
    // Compter `aujourd’hui + livraison` déclarerait en retard toute commande
    // expédiée la veille de sa date promise, le matin même de sa livraison —
    // exactement le faux positif que ce workflow existe pour éviter.
    //
    // Écart assumé par rapport à la formule littérale du brief
    // (`addBusinessDays(aujourd’hui, 1)`), au nom de son propre principe :
    // le plancher est le minimum PHYSIQUEMENT ATTEIGNABLE.
    return addBusinessDays(aujourdhui, Math.max(0, livr - 1 - ancienneteStatut), f);
  }
  return null; // Livree : hors flux
}

/** Calculs de délai communs à toutes les branches de décision. */
function evaluer(commande, etat, cfg, aujourdhui) {
  var f = cfg.JOURS_FERIES;
  var anciennete = diffBusinessDays(etat.statut_depuis, aujourdhui, f);
  var plancher = etaPlancher(commande.status, aujourdhui, anciennete, cfg);
  var promise = commande.delivery_date;
  var enRetard = Boolean(plancher) && plancher > promise;
  var eta = !plancher ? promise : plancher > promise ? plancher : promise;

  // Ce qu'on DÉTECTE (eta) et ce qu'on PROMET (date_engagement) sont deux
  // choses distinctes. Sans retard, la date promise d'origine tient et ne
  // reçoit aucune marge : on ne repousse pas une commande qui va bien.
  var engagement = enRetard
    ? addBusinessDays(eta, Number(cfg.MARGE_ENGAGEMENT_JOURS) || 0, f)
    : eta;

  return {
    anciennete_statut: anciennete,
    eta_plancher: plancher,
    eta: eta,
    date_engagement: engagement,
    en_retard: enRetard,
    jours_de_retard: enRetard ? diffBusinessDays(promise, eta, f) : 0
  };
}

/* ---------------------------------------------------------------------------
 * 5. Alertes internes
 * ---------------------------------------------------------------------------
 * Fonction PURE de l'état : elle ne dépend pas de ce qui a été envoyé au
 * client. Le digest est donc produit même les week-ends et jours fériés,
 * contrairement aux emails clients.
 *
 * Un seul motif par commande et par jour : celui de plus haute priorité.
 * ------------------------------------------------------------------------- */

var MOTIFS_INTERNES = [
  {
    code: 'DEUXIEME_GLISSEMENT',
    // « Appeler le client » serait une consigne que l'outil ne peut pas
    // soutenir : l'ERP ne fournit pas de numéro de téléphone, seulement un
    // email. On demande une reprise en main, et le digest donne la matière.
    libelle: 'Deuxième date manquée — reprendre le dossier à la main',
    gravite: 'traiter', abrev: 'G2'
  },
  { code: 'ESCALADE_CRITIQUE', libelle: 'Appel commercial, envisager une substitution', gravite: 'traiter', abrev: 'EC' },
  { code: 'PLAFOND_MESSAGES_ATTEINT', libelle: 'Le robot s’arrête, reprise humaine', gravite: 'traiter', abrev: 'PL' },
  { code: 'ESCALADE_FOURNISSEUR', libelle: 'Relance ou escalade fournisseur', gravite: 'traiter', abrev: 'EF' },
  {
    code: 'CONTACT_MANQUANT',
    libelle: 'Adresse email absente ou invalide — reprendre le contact à la main',
    gravite: 'traiter',
    abrev: 'CM'
  },
  { code: 'BLOCAGE_INTERNE', libelle: 'Blocage interne, tout est en stock', gravite: 'surveiller', abrev: 'BI' },
  { code: 'INCIDENT_TRANSPORTEUR', libelle: 'Incident transporteur possible', gravite: 'surveiller', abrev: 'IT' },
  {
    code: 'RETARD_FOURNISSEUR_NOUVEAU',
    libelle: 'Nouveau retard fournisseur — pour information',
    gravite: 'surveiller', abrev: 'NF'
  }
];

function libelleMotif(code) {
  for (var i = 0; i < MOTIFS_INTERNES.length; i++) {
    if (MOTIFS_INTERNES[i].code === code) return MOTIFS_INTERNES[i].libelle;
  }
  return code;
}

/** Contrôle minimal : une adresse exploitable par un serveur d’envoi. */
function emailValide(adresse) {
  return /^[^\s@]+@[^\s@.]+\.[^\s@]+$/.test(String(adresse || '').trim());
}

/** Renvoie la liste des motifs applicables, non triés. */
function motifsInternes(commande, etat, calc, cfg) {
  var motifs = [];
  var st = commande.status;

  if (calc.en_retard && calc.jours_de_retard > cfg.SEUIL_ESCALADE_CRITIQUE) {
    motifs.push('ESCALADE_CRITIQUE');
  }
  if (
    st === 'Commande_confirmee' &&
    calc.en_retard &&
    calc.jours_de_retard > cfg.SEUIL_ESCALADE_FOURNISSEUR
  ) {
    motifs.push('ESCALADE_FOURNISSEUR');
  }
  if (st === 'En_preparation' && calc.anciennete_statut > cfg.SEUIL_PREPARATION_BLOQUEE) {
    motifs.push('BLOCAGE_INTERNE');
  }
  if (st === 'Expediee' && calc.anciennete_statut > cfg.SEUIL_EXPEDITION_BLOQUEE) {
    motifs.push('INCIDENT_TRANSPORTEUR');
  }
  // Le jour où un retard fournisseur est détecté, le support doit le savoir —
  // pas pour agir (on n'a aucune prise sur le fournisseur), mais pour avoir la
  // visibilité qu'il n'a pas aujourd'hui, et pour reconnaître le dossier si le
  // client rappelle. C'est le seul motif purement informatif ; il ne se répète
  // pas, puisque dès le lendemain la commande n'est plus en état AUCUN.
  if (st === 'Commande_confirmee' && calc.en_retard && etat.etat_comm === 'AUCUN') {
    motifs.push('RETARD_FOURNISSEUR_NOUVEAU');
  }
  // PLAFOND_MESSAGES_ATTEINT n'est PAS un motif d'état : il traduit un
  // événement — « le moteur voulait écrire au client et le plafond l'en a
  // empêché ». Il est ajouté par `decider`, au moment où l'envoi est bloqué.
  // Le calculer ici depuis `nb_messages_client` rendrait la journée non
  // idempotente : la 1re exécution incrémente le compteur, la 2e verrait donc
  // une alerte que la 1re n'a pas produite.
  return motifs;
}

/** Garde le motif le plus prioritaire de la liste. */
function motifPrioritaire(motifs) {
  for (var i = 0; i < MOTIFS_INTERNES.length; i++) {
    if (motifs.indexOf(MOTIFS_INTERNES[i].code) !== -1) return MOTIFS_INTERNES[i].code;
  }
  return null;
}

/* ---------------------------------------------------------------------------
 * 6. Décision du message client
 * ---------------------------------------------------------------------------
 * Principe directeur :
 *   on annonce une DATE quand le blocage est dans notre périmètre ;
 *   on annonce un ENGAGEMENT DE RECONTACT quand il ne l'est pas.
 * ------------------------------------------------------------------------- */

function raisonPreparation(status) {
  if (status === 'En_preparation') return 'Elle est actuellement en préparation dans notre entrepôt.';
  if (status === 'Expediee') return 'Elle est entre les mains de notre transporteur.';
  return '';
}

/**
 * Renvoie soit null (rien à dire), soit { template, payload, maj, motif },
 * soit { deuxieme_glissement: true }.
 * Ne connaît AUCUN des filtres de suppression : ils sont appliqués par
 * `decider`, ce qui garde cette fonction lisible comme un arbre de décision.
 */
function deciderMessage(commande, etat, calc, cfg, aujourdhui) {
  var f = cfg.JOURS_FERIES;
  var st = commande.status;

  /* --- 7.3 Branche « pas en retard » ------------------------------------- */
  if (!calc.en_retard) {
    // Le fournisseur a livré alors qu'on avait dit au client n'avoir aucune
    // date. C'est la bonne nouvelle, on la donne — même si la commande est
    // repassée dans les temps entre-temps. Sans ce cas, le prochain message
    // serait un M3 « toujours en attente d'un élément fournisseur » sur une
    // commande déjà en préparation : faux, et vu par le client.
    if (
      etat.etat_comm === 'RETARD_SANS_DATE' &&
      (st === 'En_preparation' || st === 'Expediee')
    ) {
      return {
        template: 'M4',
        motif: 'Déblocage fournisseur, commande revenue dans les temps',
        payload: { eta: calc.date_engagement },
        maj: { etat_comm: 'RETARD_DATE', date_annoncee: calc.date_engagement }
      };
    }

    // M5 ne part que sur une commande dont on n'a jamais parlé. Si une date
    // ferme a déjà été annoncée, la répéter — ou pire, en annoncer une plus
    // proche — ferait redescendre l'échelle d'engagement. Le silence est la
    // bonne réponse : la date promise sera tenue.
    if (st === 'Expediee' && etat.etat_comm === 'AUCUN') {
      return {
        template: 'M5',
        motif: 'Expédition — première notification',
        payload: { eta: calc.date_engagement },
        maj: { etat_comm: 'EXPEDITION_NOTIFIEE', date_annoncee: calc.date_engagement }
      };
    }
    return null;
  }

  /* --- 7.4 Cas A : premier retard détecté -------------------------------- */
  if (etat.etat_comm === 'AUCUN') {
    if (st === 'Commande_confirmee') {
      // Blocage fournisseur : aucune visibilité, donc AUCUNE date annoncée.
      var prochain = addBusinessDays(aujourdhui, cfg.RECONTACT_PREMIER_JOURS, f);
      return {
        template: 'M1',
        motif: 'Premier retard détecté, blocage fournisseur — engagement de recontact',
        payload: { delivery_date: commande.delivery_date, date_prochain_contact: prochain },
        maj: { etat_comm: 'RETARD_SANS_DATE', date_prochain_contact: prochain, date_annoncee: '' }
      };
    }
    // Blocage borné et connu (nous ou le transporteur) : date ferme.
    return {
      template: 'M2',
      motif: 'Premier retard détecté, blocage borné — date ferme annoncée',
      payload: {
        delivery_date: commande.delivery_date,
        eta: calc.date_engagement,
        raison: raisonPreparation(st)
      },
      maj: { etat_comm: 'RETARD_DATE', date_annoncee: calc.date_engagement }
    };
  }

  /* --- 7.4 Cas B : engagement de recontact en cours ---------------------- */
  if (etat.etat_comm === 'RETARD_SANS_DATE') {
    if (st === 'En_preparation' || st === 'Expediee') {
      return {
        template: 'M4',
        motif: 'Déblocage fournisseur — date ferme annoncée',
        payload: { eta: calc.date_engagement },
        maj: { etat_comm: 'RETARD_DATE', date_annoncee: calc.date_engagement }
      };
    }
    // Toujours bloqué chez le fournisseur : le déclencheur est la date de
    // recontact, JAMAIS l'ETA (qui glisse d'un jour chaque matin).
    if (!etat.date_prochain_contact || aujourdhui >= etat.date_prochain_contact) {
      var suivant = addBusinessDays(aujourdhui, cfg.RECONTACT_RELANCE_JOURS, f);
      return {
        template: 'M3',
        motif: 'Engagement de recontact échu — point de situation',
        payload: { date_prochain_contact: suivant },
        maj: { date_prochain_contact: suivant }
      };
    }
    return null; // le silence est légitime : un engagement est en cours
  }

  /* --- 7.4 Cas C et D : une date ferme a déjà été annoncée --------------- */
  var annoncee = etat.date_annoncee;
  if (!annoncee) return null; // état incohérent : on ne promet rien de plus
  if (calc.eta <= annoncee) return null; // l'engagement tient, rien à dire

  // Un seul rattrapage automatique par commande : « un engagement raté se
  // répare, deux ne se réparent pas ». Sans `ajustement_utilise`, un colis non
  // présenté trois jours de suite déclencherait trois M6, soit exactement
  // l'email quotidien que l'on cherche à éviter.
  if (
    st === 'Expediee' &&
    !etat.ajustement_utilise &&
    diffBusinessDays(annoncee, calc.eta, f) <= 1
  ) {
    return {
      template: 'M6',
      motif: 'Ajustement d’un jour côté transporteur (rattrapage unique)',
      payload: { date_annoncee: annoncee, eta: calc.date_engagement },
      maj: { date_annoncee: calc.date_engagement, ajustement_utilise: 'oui' }
    };
  }

  // Deuxième glissement : on passe la main à un humain, pas à un email
  // automatique. L'échelle d'engagement ne redescend jamais toute seule.
  return { deuxieme_glissement: true };
}

/* ---------------------------------------------------------------------------
 * 7. Le moteur — fonction pure unique
 * ---------------------------------------------------------------------------
 *   decider({ commande, etat, config, aujourdhui })
 *     -> { action, template, payload, maj_etat, alerte_interne }
 *
 * `action` ∈ { AUCUNE, EMAIL_CLIENT, CLOTURE } : c'est la valeur sur laquelle
 * le nœud Switch route en aval.
 * ------------------------------------------------------------------------- */

function decider(entree) {
  var commande = entree.commande;
  var cfg = Object.assign({}, CONFIG_DEFAUT, entree.config || {});
  var aujourdhui = entree.aujourdhui;
  var f = cfg.JOURS_FERIES;

  // Échouer bruyamment plutôt que silencieusement : une date invalide rendrait
  // `estJourOuvre` faux et supprimerait tous les emails sans rien signaler.
  if (!parseDate(aujourdhui)) {
    throw new Error(
      'decider : `aujourdhui` doit être une date YYYY-MM-DD, reçu ' + JSON.stringify(aujourdhui)
    );
  }
  if (!commande || !commande.order_number || !parseDate(commande.delivery_date)) {
    throw new Error(
      'decider : commande invalide (order_number et delivery_date requis) — ' +
        JSON.stringify(commande)
    );
  }

  // --- État courant, complété et rafraîchi --------------------------------
  var etat = Object.assign(
    etatVierge(commande, aujourdhui),
    entree.etat ? normaliserEtat(entree.etat) : {}
  );
  if (!etat.order_number) etat.order_number = commande.order_number;
  if (!etat.premiere_vue_le) etat.premiere_vue_le = aujourdhui;
  // copies ERP, pour que la feuille reste lisible par le support
  etat.company = commande.company || etat.company;
  etat.contact_email = commande.contact_email || etat.contact_email;
  etat.delivery_date_erp = commande.delivery_date || etat.delivery_date_erp;

  // --- Reconstruction de `statut_depuis` (§5) -----------------------------
  // L'ERP ne fournit pas la date de changement de statut : si le statut vu
  // aujourd'hui diffère du dernier statut connu, c'est qu'il a changé
  // aujourd'hui — au plus tard.
  if (etat.statut_erp !== commande.status) {
    etat.statut_erp = commande.status;
    etat.statut_depuis = aujourdhui;
  }
  if (!etat.statut_depuis) etat.statut_depuis = aujourdhui;

  var base = {
    order_number: commande.order_number,
    company: commande.company,
    contact_email: commande.contact_email
  };

  /* --- Filtre 1 : commande livrée ---------------------------------------- */
  if (commande.status === 'Livree') {
    etat.etat_comm = 'CLOS';
    return {
      action: 'CLOTURE',
      template: null,
      payload: Object.assign({}, base),
      maj_etat: etat,
      alerte_interne: null,
      diagnostic: {
        motif: 'Commande livrée — dossier clos',
        eta: '',
        eta_plancher: '',
        en_retard: false,
        jours_de_retard: 0,
        anciennete_statut: diffBusinessDays(etat.statut_depuis, aujourdhui, f),
        etat_comm_avant: entree.etat ? normaliserEtat(entree.etat).etat_comm : 'AUCUN',
        etat_comm_apres: 'CLOS'
      }
    };
  }

  var etatAvant = etat.etat_comm;
  var calc = evaluer(commande, etat, cfg, aujourdhui);

  /* --- Alertes internes (indépendantes des filtres d'envoi) --------------- */
  var motifs = motifsInternes(commande, etat, calc, cfg);

  /* --- Décision du message client ---------------------------------------- */
  var msg = deciderMessage(commande, etat, calc, cfg, aujourdhui);
  if (msg && msg.deuxieme_glissement) {
    motifs.push('DEUXIEME_GLISSEMENT');
    msg = null;
  }

  /* --- Filtres de suppression d'envoi (§7.1) ------------------------------
   * Ils suppriment l'email mais ne modifient NI l'état de communication NI
   * les alertes : la décision non exécutée sera reprise le prochain jour
   * ouvré, à l'identique.                                                   */
  var suppression = null;
  if (msg) {
    if (!emailValide(commande.contact_email)) {
      // Sans adresse exploitable, l'envoi échouerait côté SendGrid sans que
      // personne ne le sache. On bascule sur une reprise humaine.
      suppression = 'CONTACT_MANQUANT';
      motifs.push('CONTACT_MANQUANT');
    } else if (entree.envois_suspendus) {
      suppression = 'COUPE_CIRCUIT';
    } else if (!estJourOuvre(aujourdhui, f)) {
      suppression = 'JOUR_NON_OUVRE';
    } else if (etat.date_dernier_message === aujourdhui) {
      suppression = 'DEJA_CONTACTE_AUJOURDHUI';
    } else if (etat.nb_messages_client >= cfg.MAX_MESSAGES_AUTO) {
      suppression = 'PLAFOND_MESSAGES_ATTEINT';
    }
    if (suppression) msg = null;
    // Un message était dû mais le robot a atteint son plafond : c'est
    // exactement le moment où un humain doit reprendre le dossier.
    if (suppression === 'PLAFOND_MESSAGES_ATTEINT') motifs.push('PLAFOND_MESSAGES_ATTEINT');
  }

  /* --- Application des mises à jour d'état -------------------------------- */
  if (msg) {
    Object.assign(etat, msg.maj);
    etat.date_dernier_message = aujourdhui;
    etat.nb_messages_client = etat.nb_messages_client + 1;
  }

  /* --- Alerte interne retenue + anti-doublon ------------------------------
   * On ré-alerte si le motif a changé (la situation s'aggrave : le support
   * doit le voir tout de suite), sinon seulement une fois la cadence écoulée.
   * Dans tous les cas, jamais deux fois le même jour — c'est ce qui rend une
   * seconde exécution du workflow strictement sans effet.                   */
  var motif = motifPrioritaire(motifs);
  var motifChange = motif !== etat.dernier_motif_escalade;
  // Une alerte levée un jour non ouvré ne consomme PAS la cadence : le digest du
  // week-end est informatif, l'équipe le filtrera. Si l'alerte n'était pas
  // rejouée le lundi, elle disparaîtrait du seul digest réellement lu.
  var joursDepuisAlerte = !etat.escalade_interne_le
    ? Infinity
    : estJourOuvre(etat.escalade_interne_le, f)
      ? diffBusinessDays(etat.escalade_interne_le, aujourdhui, f)
      : Infinity;
  var alerteDue =
    Boolean(motif) &&
    etat.escalade_interne_le !== aujourdhui &&
    (motifChange || joursDepuisAlerte >= cfg.CADENCE_ALERTE_INTERNE_JOURS);

  var alerte = null;
  if (alerteDue) {
    alerte = {
      motif: motif,
      libelle: libelleMotif(motif),
      order_number: commande.order_number,
      company: commande.company,
      contact_email: commande.contact_email,
      statut: commande.status,
      statut_depuis: etat.statut_depuis,
      delivery_date: commande.delivery_date,
      date_annoncee: etat.date_annoncee,
      eta: calc.eta,
      jours_de_retard: calc.jours_de_retard,
      nb_messages_client: etat.nb_messages_client
    };
    etat.escalade_interne_le = aujourdhui;
    etat.dernier_motif_escalade = motif;
  }
  // Le motif a disparu (la commande est repartie) : on oublie, pour que sa
  // réapparition éventuelle soit de nouveau signalée immédiatement.
  if (!motif) etat.dernier_motif_escalade = '';

  /* --- Sortie ------------------------------------------------------------- */
  var motifDecision = msg
    ? msg.motif
    : suppression
      ? {
          CONTACT_MANQUANT: 'Adresse email absente ou invalide — aucun envoi possible',
          COUPE_CIRCUIT: 'Coupe-circuit — volume anormal, tous les envois suspendus',
          JOUR_NON_OUVRE: 'Jour non ouvré — aucun email client',
          DEJA_CONTACTE_AUJOURDHUI: 'Déjà contacté aujourd’hui — plafond d’un email par jour',
          PLAFOND_MESSAGES_ATTEINT: 'Plafond de ' + cfg.MAX_MESSAGES_AUTO + ' messages atteint — reprise humaine'
        }[suppression]
      : motifRienADire(commande, etat, calc, etatAvant);

  return {
    action: msg ? 'EMAIL_CLIENT' : 'AUCUNE',
    template: msg ? msg.template : null,
    payload: msg ? Object.assign({}, base, msg.payload) : Object.assign({}, base),
    maj_etat: etat,
    alerte_interne: alerte,
    diagnostic: {
      motif: motifDecision,
      suppression: suppression,
      eta: calc.eta,
      eta_plancher: calc.eta_plancher,
      en_retard: calc.en_retard,
      jours_de_retard: calc.jours_de_retard,
      anciennete_statut: calc.anciennete_statut,
      etat_comm_avant: etatAvant,
      etat_comm_apres: etat.etat_comm,
      motifs_internes: motifs
    }
  };
}

/* ---------------------------------------------------------------------------
 * 7 bis. Décision sur tout un lot — coupe-circuit
 * ---------------------------------------------------------------------------
 * Certaines décisions ne peuvent pas se prendre commande par commande.
 * « 200 emails ce matin » n'est jamais une bonne nouvelle : c'est le signe
 * d'un problème en amont (ERP qui renvoie des dates aberrantes, table d'état
 * vidée, changement de format). Le coupe-circuit préfère ne rien envoyer et
 * réveiller un humain plutôt que d'écrire à tout le portefeuille.
 *
 * Deux passes plutôt qu'une annulation après coup : la seconde passe redécide
 * tout avec les envois suspendus, donc aucune mise à jour d'état ne subsiste
 * pour un message qui n'est pas parti. L'idempotence est préservée.
 * ------------------------------------------------------------------------- */

function deciderLot(entree) {
  var cfg = Object.assign({}, CONFIG_DEFAUT, entree.config || {});
  var etats = entree.etats || {};

  function passe(suspendu) {
    return entree.commandes.map(function (c) {
      return decider({
        commande: c,
        etat: etats[c.order_number] || null,
        config: cfg,
        aujourdhui: entree.aujourdhui,
        envois_suspendus: suspendu
      });
    });
  }

  var decisions = passe(false);
  var nb = decisions.filter(function (d) {
    return d.action === 'EMAIL_CLIENT';
  }).length;
  var seuil = Number(cfg.SEUIL_COUPE_CIRCUIT) || 0;

  if (seuil > 0 && nb > seuil) {
    return {
      decisions: passe(true),
      coupe_circuit: { actif: true, seuil: seuil, emails_bloques: nb }
    };
  }
  return {
    decisions: decisions,
    coupe_circuit: { actif: false, seuil: seuil, emails_bloques: 0 }
  };
}

/** Explique pourquoi le workflow se tait. Un client valide une automatisation
 *  quand il comprend son silence. */
function motifRienADire(commande, etat, calc, etatAvant) {
  if (!calc.en_retard) {
    if (commande.status === 'Expediee') return 'Expédition déjà notifiée — rien de nouveau';
    return 'Dans les temps — rien à signaler';
  }
  if (etatAvant === 'RETARD_SANS_DATE') {
    return 'Engagement de recontact en cours jusqu’au ' + etat.date_prochain_contact;
  }
  if (etatAvant === 'RETARD_DATE' || etatAvant === 'EXPEDITION_NOTIFIEE') {
    return 'Date annoncée (' + etat.date_annoncee + ') toujours tenable';
  }
  return 'Aucune action';
}

/* ---------------------------------------------------------------------------
 * 8. Rendu des messages clients
 * ---------------------------------------------------------------------------
 * Ton : sobre, factuel, professionnel. Pas d'excuse de circonstance. Le
 * fournisseur n'est jamais nommé. Aucune date n'est avancée pour adoucir.
 *
 * Un template ne produit PAS du texte : il produit une structure
 * (objet, paragraphes, encart, appel à l'action). Le rendu texte et le rendu
 * HTML consomment tous deux cette structure. C'est ce qui garantit que les
 * deux parties du multipart disent exactement la même chose — un client mail
 * qui affiche le texte brut ne peut pas lire autre chose que l'HTML.
 * ------------------------------------------------------------------------- */

function signature(cfg) {
  return (
    cfg.SIGNATURE_PRENOM +
    '\n' +
    cfg.SIGNATURE_ROLE +
    ' — ' +
    cfg.SIGNATURE_SOCIETE +
    '\n' +
    cfg.SIGNATURE_TEL
  );
}

/* --- Lien de suivi --------------------------------------------------------
 * L'ERP n'expose pas de numéro de suivi transporteur. On ne fabrique donc pas
 * un faux lien de tracking : le lien pointe vers l'état de la commande tel que
 * le workflow le connaît — la même table d'état que lit le support.
 *
 * Le jeton évite qu'une URL soit devinable en incrémentant un numéro de
 * commande. C'est de l'obfuscation, PAS de l'authentification : côté portail,
 * il doit être remplacé par une signature HMAC vérifiée serveur. Le hachage
 * est écrit à la main pour rester portable : selon la version et la
 * configuration de l'instance n8n, l'accès aux modules Node natifs depuis un
 * nœud Code n'est pas garanti. Une fois l'instance connue, `crypto.createHmac`
 * ou le nœud Crypto natif font mieux.
 * ------------------------------------------------------------------------ */

function hachage(chaine, graine) {
  var h = graine >>> 0;
  for (var i = 0; i < chaine.length; i++) {
    h ^= chaine.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h >>> 0;
}

function jetonSuivi(orderNumber, cfg) {
  var base = (cfg.SECRET_LIEN_SUIVI || '') + '|' + orderNumber;
  return (hachage(base, 2166136261).toString(36) + hachage(base + '|2', 40389).toString(36)).slice(0, 12);
}

function lienSuivi(orderNumber, cfg) {
  if (!cfg.URL_PORTAIL_SUIVI) return '';
  return (
    cfg.URL_PORTAIL_SUIVI.replace(/\/+$/, '') +
    '/' +
    encodeURIComponent(orderNumber) +
    '?k=' +
    jetonSuivi(orderNumber, cfg)
  );
}

/* --- Composition ---------------------------------------------------------- */

var LARGEUR = 74;

/** Justifie un paragraphe à `largeur` colonnes (césure calculée au rendu). */
function justifier(paragraphe, largeur) {
  var mots = String(paragraphe).split(/\s+/).filter(Boolean);
  var lignes = [];
  var courante = '';
  for (var i = 0; i < mots.length; i++) {
    if (!courante) courante = mots[i];
    else if ((courante + ' ' + mots[i]).length <= largeur) courante += ' ' + mots[i];
    else {
      lignes.push(courante);
      courante = mots[i];
    }
  }
  if (courante) lignes.push(courante);
  return lignes.join('\n');
}

function echapper(v) {
  return String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

