 * Produit la réponse de l'API ERP : un objet par commande, 6 champs ERP
 * + `_cas_teste` (conservé pour la démo, ignoré par le moteur).
 *
 * `jour` (1-based) sélectionne le statut via `_evolution`, ce qui permet au
 * harness de faire évoluer les commandes sur plusieurs journées.
 */
function resoudreCommandes(commandes, reference, jour, joursFeries) {
  var j = Number(jour) || 1;
  return commandes.map(function (c) {
    var status = c.status;
    var evolutions = c._evolution || [];
    for (var i = 0; i < evolutions.length; i++) {
      if (j >= Number(evolutions[i].a_partir_du_jour)) status = evolutions[i].status;
    }
    return {
      order_number: c.order_number,
      company: c.company,
      contact_email: c.contact_email,
      order_date: resoudreDate(c.order_date, reference, joursFeries),
      delivery_date: resoudreDate(c.delivery_date, reference, joursFeries),
      status: status,
      _cas_teste: c._cas_teste || ''
    };
  });
}

