/* --- Rendu texte ----------------------------------------------------------- */

function rendreTexte(msg, cfg) {
  var blocs = msg.paragraphes
    .filter(function (p) {
      return p !== null && p !== undefined && String(p).trim() !== '';
    })
    .map(function (p) {
      return justifier(p, LARGEUR);
    });

  var sortie = 'Bonjour,\n\n' + blocs.join('\n\n');

  if (msg.lien) {
    sortie += '\n\nSuivre l’état de votre commande :\n' + msg.lien;
  }

  return sortie + '\n\n' + signature(cfg);
}

/* --- Rendu HTML -------------------------------------------------------------
 * Contraintes propres à l'email, qui expliquent chaque choix ci-dessous :
 *   - tables imbriquées et styles INLINE : Outlook (moteur Word) ignore le CSS
 *     externe, les flex/grid et la plupart des sélecteurs ;
 *   - largeur fixe 600 px, l'unité de base historique des clients mail ;
 *   - bouton « bulletproof » : une table stylée, doublée d'un bloc VML pour
 *     Outlook Windows qui n'applique pas padding/border-radius sur un lien ;
 *   - AUCUNE image : ~40 % des destinataires B2B bloquent les images par
 *     défaut. Le logo est typographique, donc toujours visible. Renseigner
 *     `MARQUE_LOGO_URL` bascule automatiquement sur une image hébergée, avec
 *     le texte alternatif pour le cas bloqué ;
 *   - preheader masqué : la ligne de prévisualisation des boîtes mail, sinon
 *     remplie avec le début du corps ;
 *   - mode sombre : `color-scheme` + une media query ; le support est inégal,
 *     d'où des couleurs qui restent lisibles même si elle est ignorée.
 * -------------------------------------------------------------------------- */

function logoHtml(cfg) {
  var couleur = cfg.MARQUE_COULEUR;
  var nom = echapper(cfg.MARQUE_NOM);

  if (cfg.MARQUE_LOGO_URL) {
    return (
      '<img src="' + echapper(cfg.MARQUE_LOGO_URL) + '" width="132" height="36" alt="' + nom +
      '" style="display:block;border:0;outline:none;text-decoration:none;height:36px;width:auto;">'
    );
  }

  return (
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>' +
    '<td width="38" height="38" align="center" valign="middle" bgcolor="' + couleur + '"' +
    ' style="width:38px;height:38px;background-color:' + couleur + ';border-radius:7px;' +
    'font-family:Georgia,\'Times New Roman\',serif;font-size:19px;font-weight:bold;' +
    'color:#ffffff;line-height:38px;text-align:center;">' +
    echapper(cfg.MARQUE_MONOGRAMME) +
    '</td>' +
    '<td style="padding-left:12px;">' +
    '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:19px;font-weight:bold;' +
    'letter-spacing:.1em;color:' + couleur + ';line-height:1.1;">' + nom + '</div>' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10px;letter-spacing:.09em;' +
    'text-transform:uppercase;color:#7A868F;line-height:1.5;">' +
    echapper(cfg.MARQUE_BASELINE) + '</div>' +
    '</td></tr></table>'
  );
}

function encartHtml(lignes, cfg) {
  var html =
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"' +
    ' style="width:100%;background-color:#F4F6F7;border:1px solid #E2E8EB;border-radius:8px;"' +
    ' class="encart"><tr><td style="padding:20px 24px;">' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="width:100%;">';

  lignes.forEach(function (l, i) {
    var haut = i === 0 ? '0' : '10px';
    html +=
      '<tr>' +
      '<td style="padding:' + haut + ' 0 0 0;font-family:Arial,Helvetica,sans-serif;font-size:12px;' +
      'color:#63707A;line-height:1.5;" class="sourdine">' + echapper(l[0]) + '</td>' +
      '<td align="right" style="padding:' + haut + ' 0 0 0;font-family:Arial,Helvetica,sans-serif;' +
      'font-size:' + (l[2] ? '15px' : '13px') + ';font-weight:bold;line-height:1.5;color:' +
      (l[2] ? cfg.MARQUE_COULEUR : '#1A2024') + ';" class="' + (l[2] ? 'valeur-forte' : 'valeur') + '">' +
      echapper(l[1]) +
      '</td></tr>';
  });

  return html + '</table></td></tr></table>';
}

