/* --- Point d'entrée --------------------------------------------------------
 * rendre({ template, payload, config })
 *   -> { to, subject, body_text, body_html, template_id, lien_suivi }
 * ------------------------------------------------------------------------- */

function rendre(entree) {
  var cfg = Object.assign({}, CONFIG_DEFAUT, entree.config || {});
  var t = TEMPLATES[entree.template];
  if (!t) throw new Error('Template inconnu : ' + entree.template);

  var p = entree.payload || {};
  var objet = t.objet(p);

  var msg = {
    objet: objet,
    // Le titre affiché en tête du mail reprend l'objet privé de son préfixe
    // « Commande XXX — » : le numéro est déjà dans l'encart, le répéter deux
    // fois à 40 px d'intervalle est du bruit.
    titre: objet.replace(/^Commande\s+\S+\s+—\s+/, function (m) {
      return '';
    }),
    apercu: t.apercu(p),
    paragraphes: t.paragraphes(p),
    encart: t.encart(p),
    order_number: p.order_number,
    lien: lienSuivi(p.order_number, cfg)
  };
  msg.titre = msg.titre.charAt(0).toUpperCase() + msg.titre.slice(1);

  return {
    to: p.contact_email,
    subject: objet,
    body_text: rendreTexte(msg, cfg),
    body_html: rendreHtml(msg, cfg),
    template_id: entree.template,
    lien_suivi: msg.lien
  };
}

/* ---------------------------------------------------------------------------
 * 9. Digest interne
 * ---------------------------------------------------------------------------
 * Un seul email quotidien, groupé par action attendue. Jamais une alerte par
 * commande : c'est ce qui distingue un outil d'aide à la décision d'une
 * nouvelle source de bruit pour une équipe de 4 personnes.
 * ------------------------------------------------------------------------- */

function construireDigest(alertes, cfg, aujourdhui, contexte) {
  var conf = Object.assign({}, CONFIG_DEFAUT, cfg || {});
  var ctx = contexte || {};
  var groupes = [];

  for (var i = 0; i < MOTIFS_INTERNES.length; i++) {
    var m = MOTIFS_INTERNES[i];
    var lignes = alertes.filter(function (a) {
      return a && a.motif === m.code;
    });
    if (lignes.length) groupes.push({ motif: m.code, libelle: m.libelle, lignes: lignes });
  }

  var total = groupes.reduce(function (n, g) {
    return n + g.lignes.length;
  }, 0);

  var corps = [];
  corps.push('Suivi des commandes — ' + formatFr(aujourdhui));
  corps.push('');

  // Le coupe-circuit passe avant tout le reste : tant qu'il est actif, aucun
  // client n'a été prévenu de quoi que ce soit ce matin.
  if (ctx.coupe_circuit && ctx.coupe_circuit.actif) {
    corps.push('!!! COUPE-CIRCUIT ACTIF — AUCUN EMAIL CLIENT N’EST PARTI CE MATIN !!!');
    corps.push('');
    corps.push(
      '  ' + ctx.coupe_circuit.emails_bloques + ' messages auraient dû partir, pour un seuil de ' +
        ctx.coupe_circuit.seuil + '.'
    );
    corps.push('  Un volume pareil signale un problème en amont, pas un besoin réel.');
    corps.push('  À vérifier : la réponse de l’ERP et la table d’état, avant de relancer.');
    corps.push('');
  }

  if (!total) {
    corps.push('Aucune commande ne demande d’action interne aujourd’hui.');
  } else {
    corps.push(
      total + ' commande' + (total > 1 ? 's demandent' : ' demande') + ' une action interne.'
    );
    for (var g = 0; g < groupes.length; g++) {
      var gr = groupes[g];
      corps.push('');
      corps.push('--- ' + gr.libelle + ' (' + gr.lignes.length + ') ---');
      for (var l = 0; l < gr.lignes.length; l++) {
        corps.push('  ' + ligneDigest(gr.lignes[l]));
      }
    }
  }
  corps.push('');
  corps.push('— Workflow de suivi des commandes (mode ' + conf.MODE + ')');

  return {
    to: conf.EMAIL_SUPPORT,
    subject:
      'Suivi commandes ' +
      formatFr(aujourdhui) +
      ' — ' +
      total +
      ' action' +
      (total > 1 ? 's' : '') +
      ' interne' +
      (total > 1 ? 's' : ''),
    body_text: corps.join('\n'),
    nb_alertes: total,
    groupes: groupes
  };
}

/**
 * Une ligne de digest doit permettre d'agir SANS ouvrir l'ERP : le contact, ce
 * qu'on a promis, et ce qui a déjà été dit au client. Une alerte qui oblige à
 * aller chercher l'information ailleurs ne fait pas gagner de temps.
 */
function ligneDigest(a) {
  var bouts = [a.order_number, a.company];
  bouts.push('statut ' + a.statut + ' depuis le ' + formatFr(a.statut_depuis));
  if (a.jours_de_retard > 0) bouts.push(a.jours_de_retard + ' j ouvrés de retard');
  bouts.push('promis le ' + formatFr(a.delivery_date));
  if (a.date_annoncee) bouts.push('date annoncée au client : ' + formatFr(a.date_annoncee));
  if (a.nb_messages_client) bouts.push(a.nb_messages_client + ' message(s) envoyé(s)');
  if (a.contact_email) bouts.push(a.contact_email);
  return bouts.join(' — ');
}

/* ---------------------------------------------------------------------------
 * 9 bis. Tickets — le suivi interne dans le temps
 * ---------------------------------------------------------------------------
 * Un digest quotidien dit ce qui se passe aujourd'hui ; il ne garde la trace
 * d'aucun dossier. Une commande qui traîne trois semaines apparaît dans quinze
 * emails différents, et personne ne sait qui s'en occupe.
 *
 * Le ticket résout exactement ça : UN ticket par commande — jamais un par
 * alerte, sinon on recrée le spam qu'on a passé tout le workflow à éviter.
 *   - il naît à la première alerte ;
 *   - il reçoit un commentaire les jours où quelque chose arrive (une alerte,
 *     ou un email parti au client) ;
 *   - il se ferme tout seul à la livraison.
 *
 * Le fil de commentaires DEVIENT l'historique de la commande, emails de
 * relance compris. C'est ce que le support n'a nulle part aujourd'hui.
 *
 * Cette fonction ne connaît ni Jira, ni Linear, ni Notion : elle produit des
 * intentions (`creer`, `commenter`, `cloturer`). Un seul nœud du workflow les
 * traduit pour la plateforme choisie. En changer coûte un nœud.
 * ------------------------------------------------------------------------- */

function priorite(motif) {
  for (var i = 0; i < MOTIFS_INTERNES.length; i++) {
    if (MOTIFS_INTERNES[i].code === motif) {
      return MOTIFS_INTERNES[i].gravite === 'traiter' ? 'Haute' : 'Normale';
    }
  }
  return 'Normale';
}

/** Le résumé de situation, tel qu'on l'écrit dans la description du ticket. */
function situationTicket(commande, etat, diag, cfg) {
  var l = [];
  l.push('Commande      : ' + commande.order_number);
  l.push('Client        : ' + commande.company + ' — ' + commande.contact_email);
  l.push('Statut ERP    : ' + commande.status.replace(/_/g, ' ') +
    ' depuis le ' + formatFr(etat.statut_depuis));
  l.push('Promis le     : ' + formatFr(commande.delivery_date) +
    (diag.en_retard ? '  (' + diag.jours_de_retard + ' j ouvrés de retard)' : ''));
  l.push('Date annoncée : ' + (etat.date_annoncee ? formatFr(etat.date_annoncee) : 'aucune'));
  if (etat.date_prochain_contact) {
    l.push('Recontact dû  : ' + formatFr(etat.date_prochain_contact));
  }
  l.push('Messages déjà envoyés : ' + etat.nb_messages_client + ' / ' + cfg.MAX_MESSAGES_AUTO +
    (etat.date_dernier_message ? ' (dernier le ' + formatFr(etat.date_dernier_message) + ')' : ''));
  return l.join('\n');
}

/**
 * planifierTickets({ lignes, config, aujourdhui })
 *   lignes : [{ commande, decision, message | null }]
 *   -> [{ operation, order_number, ticket_ref, titre, corps, etiquettes, priorite, motif }]
 */
function planifierTickets(entree) {
  var cfg = Object.assign({}, CONFIG_DEFAUT, entree.config || {});
  var aujourdhui = entree.aujourdhui;
  var ops = [];

  (entree.lignes || []).forEach(function (l) {
    var c = l.commande;
    var d = l.decision;
    var etat = d.maj_etat;
    var ref = etat.ticket_ref || '';
    var alerte = d.alerte_interne;

    /* --- Clôture : la commande est livrée ------------------------------- */
    if (d.action === 'CLOTURE') {
      // Uniquement le jour de la TRANSITION vers CLOS. Sans cette condition,
      // une commande livrée refermerait son ticket chaque matin, indéfiniment.
      if (ref && d.diagnostic.etat_comm_avant !== 'CLOS') {
        ops.push({
          operation: 'cloturer',
          order_number: c.order_number,
          company: c.company,
          ticket_ref: ref,
          titre: '',
          corps:
            formatFr(aujourdhui) + ' — Commande livrée.\n' +
            'Le workflow ferme ce ticket automatiquement.',
          etiquettes: [],
          priorite: '',
          motif: 'LIVREE'
        });
      }
      return;
    }

    /* --- Création : première alerte sur cette commande ------------------- */
    if (alerte && !ref) {
      ops.push({
        operation: 'creer',
        order_number: c.order_number,
        company: c.company,
        contact_email: c.contact_email,
        ticket_ref: '',
        titre: '[' + c.order_number + '] ' + c.company + ' — ' + alerte.libelle,
        corps:
          situationTicket(c, etat, d.diagnostic, cfg) + '\n\n' +
          'Motif : ' + alerte.libelle + '\n\n' +
          'Ce ticket est alimenté chaque matin par le workflow de suivi des\n' +
          'commandes : un commentaire par journée où quelque chose se passe,\n' +
          'emails clients compris. Il se ferme seul à la livraison.',
        etiquettes: etiquettes(c, alerte.motif, cfg),
        priorite: priorite(alerte.motif),
        motif: alerte.motif
      });
      return;
    }

    /* --- Commentaire : il se passe quelque chose sur un dossier ouvert --- */
    if (ref && (alerte || l.message)) {
      var lignesCommentaire = [formatFr(aujourdhui)];

      if (l.message) {
        lignesCommentaire.push(
          '· Email ' + d.template + ' envoyé à ' + c.contact_email +
          '\n  « ' + l.message.subject + ' »'
        );
      }
      if (alerte) {
        lignesCommentaire.push(
          '· Alerte : ' + alerte.libelle +
          (d.diagnostic.en_retard ? ' (' + d.diagnostic.jours_de_retard + ' j ouvrés de retard)' : '')
        );
      }
      lignesCommentaire.push(
        '· Statut ' + c.status.replace(/_/g, ' ') +
        ' · ETA ' + formatFr(d.diagnostic.eta) +
        (etat.date_annoncee ? ' · annoncé au client : ' + formatFr(etat.date_annoncee) : ' · aucune date annoncée')
      );

      ops.push({
        operation: 'commenter',
        order_number: c.order_number,
        company: c.company,
        ticket_ref: ref,
        titre: '',
        corps: lignesCommentaire.join('\n'),
        etiquettes: [],
        priorite: alerte ? priorite(alerte.motif) : '',
        motif: alerte ? alerte.motif : 'EMAIL_CLIENT'
      });
    }
  });

  return ops;
}

function etiquettes(commande, motif, cfg) {
  var prefixe = cfg.TICKET_PREFIXE_ETIQUETTE || 'suivi';
  return [
    prefixe,
    prefixe + '-' + commande.order_number,
    prefixe + '-' + String(motif).toLowerCase().replace(/_/g, '-')
  ];
}

/* ---------------------------------------------------------------------------
 * 10. Résolution du jeu de test
 * ---------------------------------------------------------------------------
 * Outillage de FIXTURE, pas de logique métier. Il est ici — et pas dans le
 * harness — pour que le nœud `Mock API ERP` et la recette résolvent les
 * dates relatives du dataset exactement de la même façon.
 *
 * Le jour où l'on branche l'API ERP réelle, cette section devient morte : le
 * nœud HTTP Request renvoie déjà des dates absolues.
 * ------------------------------------------------------------------------- */

/** { ouvres: n } | { calendaires: n } | 'YYYY-MM-DD' | '' -> 'YYYY-MM-DD' | '' */
function resoudreDate(spec, reference, joursFeries) {
  if (spec === '' || spec === null || spec === undefined) return '';
  if (typeof spec === 'string') return spec;
  if (typeof spec.ouvres === 'number') return addBusinessDays(reference, spec.ouvres, joursFeries);
  if (typeof spec.calendaires === 'number') {
    return formatDate(ajouterJoursCalendaires(parseDate(reference), spec.calendaires));
  }
  return '';
}

/**
 * Produit la réponse de l'API ERP : un objet par commande, 6 champs ERP
 * + `_cas_teste` (conservé pour la démo, ignoré par le moteur).
 *
 * `jour` (1-based) sélectionne le statut via `_evolution`, ce qui permet au
 * harness de faire évoluer les commandes sur plusieurs journées.
 */
function resoudreCommandes(commandes, reference, jour, joursFeries) {
  var j = Number(jour) || 1;
  return commandes.map(function (c) {
    var status = c.status;
    var evolutions = c._evolution || [];
    for (var i = 0; i < evolutions.length; i++) {
      if (j >= Number(evolutions[i].a_partir_du_jour)) status = evolutions[i].status;
    }
    return {
      order_number: c.order_number,
      company: c.company,
      contact_email: c.contact_email,
      order_date: resoudreDate(c.order_date, reference, joursFeries),
      delivery_date: resoudreDate(c.delivery_date, reference, joursFeries),
      status: status,
      _cas_teste: c._cas_teste || ''
    };
  });
}

/**
 * Produit les lignes de la table d'état de départ, dates résolues, en
 * reprenant `company` / `contact_email` / `delivery_date_erp` des commandes.
 */
function resoudreEtatInitial(etatInitial, commandes, reference, joursFeries) {
  var parNumero = {};
  commandes.forEach(function (c) {
    parNumero[c.order_number] = c;
  });

  return (etatInitial || []).map(function (e) {
    var c = parNumero[e.order_number] || {};
    return {
      order_number: e.order_number,
      company: c.company || '',
      contact_email: c.contact_email || '',
      statut_erp: e.statut_erp || '',
      statut_depuis: resoudreDate(e.statut_depuis, reference, joursFeries),
      delivery_date_erp: c.delivery_date || '',
      date_annoncee: resoudreDate(e.date_annoncee, reference, joursFeries),
      etat_comm: e.etat_comm || 'AUCUN',
      date_dernier_message: resoudreDate(e.date_dernier_message, reference, joursFeries),
      nb_messages_client: Number(e.nb_messages_client) || 0,
      date_prochain_contact: resoudreDate(e.date_prochain_contact, reference, joursFeries),
      escalade_interne_le: resoudreDate(e.escalade_interne_le, reference, joursFeries),
      premiere_vue_le: resoudreDate(e.premiere_vue_le, reference, joursFeries),
      dernier_motif_escalade: e.dernier_motif_escalade || '',
      ajustement_utilise: e.ajustement_utilise || '',
      ticket_ref: e.ticket_ref || ''
    };
  });
}

// --- Code propre à ce nœud ---
var cfg = $('Config').first().json;
// dateDuJour() vient du moteur : il contrôle le format et retombe sur UTC si
// Intl est indisponible, plutôt que de rendre la date invalide en silence.
var aujourdhui = cfg.DATE_EVALUATION || dateDuJour(cfg.FUSEAU);
// Les dates du jeu de test sont relatives à cette ancre. La laisser vide
// revient à toujours rejouer le jour 1 ; la figer permet de faire avancer
// DATE_EVALUATION seule, et donc de rejouer le lendemain.
var ancreJeu = cfg.DATE_REFERENCE_JEU || aujourdhui;

var alertes = $input.all()
  .map(function (i) { return i.json._decision && i.json._decision.alerte_interne; })
  .filter(Boolean);

var premier = $input.first();
var coupeCircuit = premier ? premier.json._coupe_circuit : null;

// Le digest email n’est produit que si le canal le demande : par
// defaut les alertes partent en tickets, qui gardent la trace des dossiers.
if (cfg.CANAL_ALERTE === 'ticket') return [];

var digest = construireDigest(alertes, cfg, aujourdhui, { coupe_circuit: coupeCircuit });

return [{
  json: {
    date_execution: aujourdhui,
    to: digest.to,
    objet: digest.subject,
    corps_complet: digest.body_text,
    nb_alertes: digest.nb_alertes
  }
}];

