        ['Commande', p.order_number, false],
        ['Statut', 'remise au transporteur', false],
        ['Livraison prévue', formatFr(p.eta), true]
      ];
    },
    paragraphes: function (p) {
      return [
        'Votre commande ' + p.order_number + ' a été remise à notre transporteur.' +
          ' Livraison prévue le ' + formatFr(p.eta) + '.'
      ];
    }
  },

  M6: {
    libelle: 'Ajustement d’un jour',
    objet: function (p) {
      return 'Commande ' + p.order_number + ' — livraison décalée au ' + formatFr(p.eta);
    },
    apercu: function (p) {
      return 'Nouvelle présentation le ' + formatFr(p.eta) + '.';
    },
    encart: function (p) {
      return [
        ['Commande', p.order_number, false],
        ['Présentation manquée', formatFr(p.date_annoncee), false],
        ['Nouvelle présentation', formatFr(p.eta), true]
      ];
    },
    paragraphes: function (p) {
      return [
        'Votre commande ' + p.order_number + ' n’a pas pu être livrée le ' +
          formatFr(p.date_annoncee) + '. Elle est en cours d’acheminement et sera' +
          ' présentée le ' + formatFr(p.eta) + '.'
      ];
    }
  }
};

/* --- Rendu texte ----------------------------------------------------------- */

function rendreTexte(msg, cfg) {
  var blocs = msg.paragraphes
    .filter(function (p) {
      return p !== null && p !== undefined && String(p).trim() !== '';
    })
    .map(function (p) {
      return justifier(p, LARGEUR);
    });

  var sortie = 'Bonjour,\n\n' + blocs.join('\n\n');

  if (msg.lien) {
    sortie += '\n\nSuivre l’état de votre commande :\n' + msg.lien;
  }

  return sortie + '\n\n' + signature(cfg);
}

/* --- Rendu HTML -------------------------------------------------------------
 * Contraintes propres à l'email, qui expliquent chaque choix ci-dessous :
 *   - tables imbriquées et styles INLINE : Outlook (moteur Word) ignore le CSS
 *     externe, les flex/grid et la plupart des sélecteurs ;
 *   - largeur fixe 600 px, l'unité de base historique des clients mail ;
 *   - bouton « bulletproof » : une table stylée, doublée d'un bloc VML pour
 *     Outlook Windows qui n'applique pas padding/border-radius sur un lien ;
 *   - AUCUNE image : ~40 % des destinataires B2B bloquent les images par
 *     défaut. Le logo est typographique, donc toujours visible. Renseigner
 *     `MARQUE_LOGO_URL` bascule automatiquement sur une image hébergée, avec
 *     le texte alternatif pour le cas bloqué ;
 *   - preheader masqué : la ligne de prévisualisation des boîtes mail, sinon
 *     remplie avec le début du corps ;
 *   - mode sombre : `color-scheme` + une media query ; le support est inégal,
 *     d'où des couleurs qui restent lisibles même si elle est ignorée.
 * -------------------------------------------------------------------------- */

